#include <stdio.h>
/* ex10：二进制指数退避——冲突后为什么要「随机等一会儿」
 * CSMA/CD 冲突后：k = min(重传次数, 10)，从 [0, 2^k - 1] 中随机取 r，
 * 等待 r 个争用期（512 bit 时间）后重传；16 次仍失败则丢弃并报错。
 * 这个「指数增长的随机窗口」让重负载下的重传分散开，
 * 避免「一冲突就全体同时重传」的雪崩。本程序算每轮的平均退避时间。*/
int main(void) {
    double slot_us = 51.2;         /* 10Mbps 以太网的争用期 512 bit = 51.2us */
    printf("争用期（slot time）= %.1f us\n", slot_us);
    printf("二进制指数退避：k = min(重传次数, 10)，r 均匀取自 [0, 2^k - 1]\n");
    printf("------------------------------------------------------------------\n");
    printf("%-10s %-6s %-13s %-16s %s\n", "retry", "k", "range", "avg_slot", "avg_wait(us)");

    for (int i = 1; i <= 12; i++) {
        int k = (i < 10) ? i : 10;
        int range = (1 << k) - 1;              /* 随机取值上界 2^k - 1 */
        double avg_slot = range / 2.0;
        char buf[24];
        if (k >= 10) snprintf(buf, sizeof(buf), "0..%d(cap)", range);
        else         snprintf(buf, sizeof(buf), "0..%d", range);
        printf("%-10d %-6d %-13s %-16.1f %.1f\n", i, k, buf, avg_slot, avg_slot * slot_us);
    }
    printf("------------------------------------------------------------------\n");

    printf("\n示例：同一帧连续冲突 3 次\n");
    for (int i = 1; i <= 3; i++) {
        int range = (1 << i) - 1;
        printf("  第 %d 次冲突 -> k=%d，随机取 [0,%d]，平均等 %.1f 个争用期 = %.1f us\n",
               i, i, range, range / 2.0, range / 2.0 * slot_us);
    }
    printf("\n结论：\n");
    printf("  1) 退避窗口随冲突次数「指数增长」，冲突越多等得越久，自动抑制拥塞；\n");
    printf("  2) k 封顶 10（范围 0..1023），防止窗口无限膨胀；\n");
    printf("  3) 第 10 次冲突后平均要等 511.5 个争用期 = 26.2 ms ——\n");
    printf("     这就是重载网络「越堵越慢」的量化来源；16 次失败即丢弃并上报上层；\n");
    printf("  4) 无线 CSMA/CA 用的是同一套退避思想（但用 ACK 确认代替冲突检测）。\n");
    return 0;
}
